# Let me identify connected regions for each color
from collections import deque

def find_connected_regions(grid):
    """Find all connected regions of the same non-black color"""
    regions = {}
    visited = set()

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                region = [(r, c)]
                queue = deque([(r, c)])

                while queue:
                    rr, cc = queue.popleft()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                region.append((nr, nc))
                                visited.add((nr, nc))
                                queue.append((nr, nc))

                regions[color] = region

    return regions

